window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c15005ebde34e67b"]={"versions": [{"id": "FIG-c15005ebde34e67b", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Diagnose-Eigenschaften eines <code>SoftwareCluster</code> im Kontext der AUTOSAR Adaptive Platform (Manifest Specification, Diagnostic Extract). Das Diagramm spezifiziert die Metamodell-Struktur für softwarecluster-spezifische Diagnoseadressen, externe Authentifizierung, Diagnose-Validierungskonfigurationen sowie die Referenzierung von Diagnose-Beschreibungen aus dem Diagnostic Extract.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>SoftwareCluster</code> (Spezialisierung von <code>ARElement</code>): Besitzt Attribute <code>typeApproval: String [0..1]</code>, <code>vendorId: PositiveInteger</code> und <code>version: StrongRevisionLabelString</code>. Hält eine gerichtete Assoziation <code>+diagnosticExtract 0..1</code> auf <code>DiagnosticContributionSet</code> sowie eine Komposition <code>+diagnosticProps 0..1</code> zu <code>SoftwareClusterDiagnosticProps</code>.</li>\n<li><code>SoftwareClusterDiagnosticProps</code>: Besitzt das Attribut <code>powerDownTime: PositiveInteger [0..1]</code>. Enthält per Komposition:</li>\n<li><code>+diagnosticAddress 0..*</code> (<code>«atpSplitable»</code>) zu <code>SoftwareClusterDiagnosticAddress</code>.</li>\n<li><code>+externalAuthentication 0..*</code> zu <code>DiagnosticExternalAuthenticationIdentification</code>.</li>\n<li><code>+validationConfiguration 0..1</code> zu <code>DiagnosticServiceValidationConfiguration</code>.</li>\n<li><code>SoftwareClusterDiagnosticAddress</code> (abstrakt): Besitzt das Attribut <code>addressSemantics: SoftwareClusterDiagnosticAddressSemanticsEnum</code>. Die Spezialisierung <code>SoftwareClusterDoipDiagnosticAddress</code> ergänzt <code>diagnosticAddress: PositiveInteger [0..1]</code>.</li>\n<li><code>«enumeration» SoftwareClusterDiagnosticAddressSemanticsEnum</code>: Definiert die Literale <code>physicalAddress</code> und <code>functionalAddress</code>.</li>\n<li><code>DiagnosticExternalAuthenticationIdentification</code>: Besitzt die Attribute <code>sourceAddressCode: PositiveInteger [0..1]</code> und <code>sourceAddressMask: PositiveInteger [0..1]</code>.</li>\n<li><code>DiagnosticServiceValidationConfiguration</code>: Referenziert über die geordneten Assoziationen <code>+manufacturerValidationOrder 0..<em> {ordered}</code> und <code>+supplierValidationOrder 0..</em> {ordered}</code> Zielobjekte vom Typ <code>DiagnosticServiceValidationMapping</code> (Spezialisierung von <code>DiagnosticSwMapping</code>).</li>\n<li>Paket <code>Diagnostic Extract</code>: Enthält <code>DiagnosticContributionSet</code> (Spezialisierung von <code>ARElement</code>), das über die Assoziation <code>+element 0..*</code> (<code>«atpVariation,atpSplitable»</code>) Elemente vom Typ <code>DiagnosticCommonElement</code> (Spezialisierung von <code>ARElement</code>) aggregiert. Eine Spezialisierung davon ist <code>DiagnosticSoftwareClusterProps</code> mit dem Attribut <code>dtcStatusAvailabilityMask: PositiveInteger</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt deklarative Datenstrukturen zur Entwurfs- und Konfigurationszeit für die Diagnoseanbindung eines Software-Clusters, einschließlich der Reihenfolge von Validierungsabläufen über geordnete Assoziationen (<code>{ordered}</code>) für hersteller- und lieferantenspezifische Validierungsschritte.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation für AUTOSAR-Modellierungs- und Manifest-Generierungswerkzeuge. Die Stereotype <code>«atpSplitable»</code> und <code>«atpVariation»</code> kennzeichnen Eigenschaften, die über mehrere ARXML-Dateifragmente aufgeteilt werden können bzw. variationspunktfähig sind. Geordnete Rollen (<code>{ordered}</code>) verlangen von Verarbeitungs-Tools die strikte Beibehaltung der Sequenz von Validierungsmappings. Pflichtattribute wie <code>vendorId</code> und <code>version</code> sind für die Identifikation zwingend bereitzustellen.</p>"}, {"id": "FIG-becd8fbcf0405380", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Diagnose-Eigenschaften eines <code>SoftwareCluster</code> im Kontext der AUTOSAR Adaptive Platform (Manifest Specification, Diagnostic Extract). Das Diagramm spezifiziert die Metamodell-Struktur für softwarecluster-spezifische Diagnoseadressen, externe Authentifizierung, Diagnose-Validierungskonfigurationen sowie die Referenzierung von Diagnose-Beschreibungen aus dem Diagnostic Extract.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>SoftwareCluster</code> (Spezialisierung von <code>ARElement</code>): Enthält Attribute <code>installationBehavior: SoftwareClusterInstallationBehaviorEnum [0..1]</code>, <code>typeApproval: String [0..1]</code>, <code>vendorId: PositiveInteger [0..1]</code> und <code>version: StrongRevisionLabelString [0..1]</code>. Hält eine Komposition <code>+diagnosticDeploymentProps 0..1</code> zu <code>SoftwareClusterDiagnosticDeploymentProps</code>.</li>\n<li><code>SoftwareClusterDiagnosticDeploymentProps</code> (Spezialisierung von <code>UploadablePackageElement</code>): Enthält das Attribut <code>powerDownTime: PositiveInteger [0..1]</code>. Hält eine Assoziation <code>+diagnosticExtract 0..1</code> auf <code>DiagnosticContributionSet</code> und komponiert:</li>\n<li><code>+diagnosticAddress 0..*</code> (<code>«atpSplitable»</code>) zu <code>SoftwareClusterDiagnosticAddress</code>.</li>\n<li><code>+externalAuthentication 0..*</code> zu <code>DiagnosticExternalAuthenticationIdentification</code>.</li>\n<li><code>+validationConfiguration 0..1</code> zu <code>DiagnosticServiceValidationConfiguration</code>.</li>\n<li><code>SoftwareClusterDiagnosticAddress</code> (abstrakt): Enthält das Attribut <code>addressSemantics: SoftwareClusterDiagnosticAddressSemanticsEnum [0..1]</code>. Spezialisierungen sind:</li>\n<li><code>SoftwareClusterDoipDiagnosticAddress</code> mit Attribut <code>diagnosticAddress: PositiveInteger [0..1]</code>.</li>\n<li><code>SoftwareClusterSovdAddress</code> mit Attribut <code>componentQualifier: String [0..1]</code>.</li>\n<li><code>«enumeration» SoftwareClusterDiagnosticAddressSemanticsEnum</code>: Definiert die Literale <code>physicalAddress</code> und <code>functionalAddress</code>.</li>\n<li><code>DiagnosticExternalAuthenticationIdentification</code>: Enthält die Attribute <code>sourceAddressCode: PositiveInteger [0..1]</code> und <code>sourceAddressMask: PositiveInteger [0..1]</code>.</li>\n<li><code>DiagnosticServiceValidationConfiguration</code>: Referenziert über die geordneten Assoziationen <code>+manufacturerValidationOrder 0..<em> {ordered}</code> und <code>+supplierValidationOrder 0..</em> {ordered}</code> Elemente vom Typ <code>DiagnosticServiceValidationMapping</code> (Spezialisierung von <code>DiagnosticSwMapping</code>).</li>\n<li>Paket <code>Diagnostic Extract</code>: Beherbergt <code>DiagnosticContributionSet</code> (Spezialisierung von <code>ARElement</code>), welches über <code>+element 0..*</code> (<code>«atpVariation,atpSplitable»</code>) auf <code>DiagnosticCommonElement</code> (Spezialisierung von <code>ARElement</code>) verweist.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt deklarative Datenstrukturen zur Entwurfs- und Konfigurationszeit für die Diagnoseanbindung eines Software-Clusters, einschließlich der Reihenfolge von Validierungsabläufen über geordnete Assoziationen (<code>{ordered}</code>) für hersteller- und lieferantenspezifische Validierungsschritte.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation für Manifest- und Werkzeugketten. Durch die Ableitung von <code>UploadablePackageElement</code> ist <code>SoftwareClusterDiagnosticDeploymentProps</code> als paketierbares Artefakt handhabbar. <code>SoftwareCluster</code>-Attribute wie <code>vendorId</code>, <code>version</code> und <code>installationBehavior</code> sind optional modellierbar (<code>[0..1]</code>). Die Spezialisierung <code>SoftwareClusterSovdAddress</code> unterstützt SOVD-basierte Diagnosepfade neben DoIP. Stereotype wie <code>«atpSplitable»</code> und geordnete Assoziationen (<code>{ordered}</code>) erfordern konforme Modellverarbeitung bei Datei-Splitting und Reihenfolgenerhaltung.</p>"}, {"id": "FIG-b10f4ec0551924cd", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Diagnose-Deployment-Eigenschaften eines <code>SoftwareCluster</code> im Kontext der AUTOSAR Adaptive Platform (Manifest Specification, Diagnostic Extract). Das Diagramm fokussiert auf das Zusammenspiel von deploybaren Software-Clustern mit Diagnose-Deployment-Eigenschaften, Service-Validierungskonfigurationen (inklusive UDS- und SOVD-Validierung) und der Referenzierung von Diagnose-Extrakten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell umfasst folgende Komponenten und Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><code>SoftwareCluster</code> (Spezialisierung von <code>UploadableDeploymentElement</code>): Enthält Attribute <code>installationBehavior: SoftwareClusterInstallationBehaviorEnum [0..1]</code>, <code>typeApproval: String [0..1]</code>, <code>vendorId: PositiveInteger [0..1]</code> und <code>version: StrongRevisionLabelString [0..1]</code>. Referenziert über eine gerichtete Assoziation <code>+diagnosticDeploymentProps 0..1</code> die Klasse <code>SoftwareClusterDiagnosticDeploymentProps</code>.</li>\n<li><code>SoftwareClusterDiagnosticDeploymentProps</code> (Spezialisierung von <code>UploadableDeploymentElement</code>): Enthält das Attribut <code>powerDownTime: PositiveInteger [0..1]</code>. Hält eine gerichtete Assoziation <code>+diagnosticExtract 0..1</code> auf <code>DiagnosticContributionSet</code> sowie eine Komposition <code>+validationConfiguration 0..1</code> zu <code>DiagnosticServiceValidationConfiguration</code>.</li>\n<li><code>DiagnosticServiceValidationConfiguration</code>: Hält drei geordnete Assoziationen:</li>\n<li><code>+manufacturerValidationOrder 0..* {ordered}</code> auf <code>DiagnosticServiceValidationMapping</code> (Spezialisierung von <code>DiagnosticSwMapping</code>).</li>\n<li><code>+supplierValidationOrder 0..* {ordered}</code> auf <code>DiagnosticServiceValidationMapping</code> (Spezialisierung von <code>DiagnosticSwMapping</code>).</li>\n<li><code>+sovdValidationOrder 0..* {ordered}</code> auf <code>DiagnosticSovdServiceValidationPortMapping</code> (Spezialisierung von <code>DiagnosticSwMapping</code>).</li>\n<li>Paket <code>Diagnostic Extract</code>: Enthält <code>DiagnosticContributionSet</code> (Spezialisierung von <code>ARElement</code>), das über <code>+element 0..*</code> (<code>«atpVariation,atpSplitable»</code>) auf <code>DiagnosticCommonElement</code> (Spezialisierung von <code>ARElement</code>) verweist.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt deklarative Datenstrukturen zur Entwurfs- und Konfigurationszeit für die Diagnoseanbindung eines Software-Clusters, einschließlich der Reihenfolge von Validierungsabläufen über geordnete Assoziationen (<code>{ordered}</code>) für hersteller- und lieferantenspezifische Validierungsschritte.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Adaptive-Platform-Manifeste. <code>SoftwareCluster</code> und <code>SoftwareClusterDiagnosticDeploymentProps</code> sind als <code>UploadableDeploymentElement</code> typisiert und über eine gerichtete Assoziation entkoppelt. Mit <code>DiagnosticSovdServiceValidationPortMapping</code> und der Assoziation <code>+sovdValidationOrder 0..* {ordered}</code> ist eine dedizierte Validierungsabfolge für SOVD-Servicestellen normativ vorgeschrieben; die Beibehaltung der Reihenfolge (<code>{ordered}</code>) ist für Modellprüfungen und Code-/Manifest-Generatoren verbindlich. Adressierungs- und Authentifizierungsmodelle für DoIP/SOVD sind aus diesem Teildiagramm ausgelagert.</p>"}], "trans": [{"from": "FIG-c15005ebde34e67b", "to": "FIG-becd8fbcf0405380", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>SoftwareCluster</code>: Attribute <code>vendorId</code> und <code>version</code> von Pflicht (<code>1..1</code>) auf optional (<code>[0..1]</code>) geändert; Attribut <code>installationBehavior: SoftwareClusterInstallationBehaviorEnum [0..1]</code> neu eingeführt.</li>\n<li><code>SoftwareClusterDiagnosticProps</code> umbenannt in <code>SoftwareClusterDiagnosticDeploymentProps</code> und erbt neu von <code>UploadablePackageElement</code>; Rolle der Komposition von <code>SoftwareCluster</code> auf <code>+diagnosticDeploymentProps 0..1</code> geändert.</li>\n<li><code>DiagnosticSoftwareClusterProps</code> (Spezialisierung von <code>DiagnosticCommonElement</code> mit Attribut <code>dtcStatusAvailabilityMask: PositiveInteger</code>) entfernt.</li>\n<li><code>SoftwareClusterDiagnosticAddress</code>: Attribut <code>addressSemantics</code> von Pflicht auf optional (<code>[0..1]</code>) geändert.</li>\n<li><code>SoftwareClusterSovdAddress</code>: Neue Spezialisierungsklasse von <code>SoftwareClusterDiagnosticAddress</code> mit Attribut <code>componentQualifier: String [0..1]</code> ergänzt.</li>\n</ul>"}, {"from": "FIG-becd8fbcf0405380", "to": "FIG-b10f4ec0551924cd", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>SoftwareCluster</code> und <code>SoftwareClusterDiagnosticDeploymentProps</code>: Basistyp von <code>ARElement</code> bzw. <code>UploadablePackageElement</code> auf <code>UploadableDeploymentElement</code> geändert.</li>\n<li>Beziehung zwischen <code>SoftwareCluster</code> und <code>SoftwareClusterDiagnosticDeploymentProps</code> von Komposition (<code>SoftwareCluster</code> besitzt <code>SoftwareClusterDiagnosticDeploymentProps</code>) zu einer gerichteten Assoziation geändert.</li>\n<li><code>DiagnosticExternalAuthenticationIdentification</code> samt Komposition <code>+externalAuthentication 0..*</code> entfernt.</li>\n<li><code>SoftwareClusterDiagnosticAddress</code> (inkl. Stereotyp <code>«atpSplitable»</code>, Rolle <code>+diagnosticAddress 0..*</code>), die Enumeration <code>SoftwareClusterDiagnosticAddressSemanticsEnum</code> sowie die abgeleiteten Klassen <code>SoftwareClusterDoipDiagnosticAddress</code> und <code>SoftwareClusterSovdAddress</code> vollständig entfernt.</li>\n<li><code>DiagnosticSovdServiceValidationPortMapping</code>: Neues Element (Spezialisierung von <code>DiagnosticSwMapping</code>) über Assoziation <code>+sovdValidationOrder 0..* {ordered}</code> von <code>DiagnosticServiceValidationConfiguration</code> angebunden.</li>\n</ul>"}]};
